-- Generated by tools/build_action_data.py; do not edit.
return {["scripts/actions/abilities/pets/automaton/provoke.lua"]={["Path"]="scripts/actions/abilities/pets/automaton/provoke.lua",["SHA256"]="532391701e82a91cd4c5e53a3cb115fc26b1daa2c540aa8afec2c482c1fdc1ef",["Text"]="-----------------------------------\n-- Provoke - Goads the target into attacking the automaton.\n-----------------------------------\n---@type TAbilityAutomaton\nlocal abilityObject = {}\n\nabilityObject.onAutomatonAbilityCheck = function(target, automaton, skill)\n    return 0\nend\n\nabilityObject.onAutomatonAbility = function(target, automaton, skill, master, action)\n    automaton:addRecast(xi.recast.ABILITY, skill:getID(), 30)\n    target:addEnmity(automaton, 1, 1800) -- Confirmed on retail.\n\n    skill:setMsg(xi.msg.basic.PROVOKE_SWITCH)\n    return 0\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/automaton/shield_bash.lua"]={["Path"]="scripts/actions/abilities/pets/automaton/shield_bash.lua",["SHA256"]="1f477c30518fe5b5540c9c73e338e8a84e58231c9a9c6a7e7b23918d4ddb5cff",["Text"]="-----------------------------------\n-- Shield Bash (Automaton)\n-- Description: Deals damage and stuns the target. Additional effect: Slow - Based on Earth Maneuvers if Hammermill is equipped.\n-- Hammermill Slow increases with tiers per Earth Maneuver, at 3, overrides Haste (tier 6) -- Confirmed in Brenner.\n-- https://wiki.ffo.jp/html/12156.html\n-----------------------------------\n---@type TAbilityAutomaton\nlocal abilityObject = {}\n\n-- Slow tier and duration based on Earth Maneuvers.\nlocal slowTable =\n{\n    [1] = { tier = 4, duration = 30 },\n    [2] = { tier = 5, duration = 50 },\n    [3] = { tier = 6, duration = 70 },\n}\n\nlocal function applyHammermillSlow(automaton, target, skill, master)\n    local power = automaton:getMod(xi.mod.AUTO_SHIELD_BASH_SLOW) * 100\n    if power <= 0 then\n        return\n    end\n\n    local slowTier = slowTable[master and master:countEffect(xi.effect.EARTH_MANEUVER) or 0]\n\n    local params =\n    {\n        [1] = { effectId = xi.effect.SLOW, power = power, duration = slowTier.duration, tier = slowTier.tier },\n    }\n\n    xi.combat.action.executeMobskillStatusEffect(automaton, target, skill, params, { messageBypass = true })\nend\n\nabilityObject.onAutomatonAbilityCheck = function(target, automaton, skill)\n    return 0\nend\n\nabilityObject.onAutomatonAbility = function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage     = automaton:getWeaponDmg()\n    params.numHits        = utils.clamp(1 + xi.automaton.getExtraHits(automaton, 1), 1, 8)\n    params.fTP            = { 1.0, 1.0, 1.0 }\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.shadowBehavior = params.numHits\n\n    local hammermillEquipped = automaton:hasAttachmentSet(xi.item.HAMMERMILL_ATTACHMENT)\n\n    if hammermillEquipped then\n        local shieldBashBonus = 1.0 + automaton:getMod(xi.mod.SHIELD_BASH) / 100\n\n        params.fTP =\n        {\n            params.fTP[1] * shieldBashBonus,\n            params.fTP[2] * shieldBashBonus,\n            params.fTP[3] * shieldBashBonus,\n        }\n\n        params.guaranteedFirstHit = true\n    end\n\n    local info = xi.mobskills.mobPhysicalMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n\n        xi.mobskills.mobStatusEffectMove(automaton, target, xi.effect.STUN, 1, 0, 6)\n\n        -- Check for Hammermill, if equipped, apply Slow based on Earth Maneuvers.\n        if hammermillEquipped then\n            applyHammermillSlow(automaton, target, skill, master)\n        end\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/axe_kick.lua"]={["Path"]="scripts/actions/abilities/pets/axe_kick.lua",["SHA256"]="8fda557a4eb40f70dc7fd7767034124766ede3bc07d475afa5cf5fc37035e5a8",["Text"]="-----------------------------------\n-- Axe Kick\n-- Family: Avatar (Shiva)\n-- Description: Deals Physical damage to a single target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.0, 2.0, 2.0 }\n    params.fTPSubsequentHits = { 2.0, 2.0, 2.0 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/back_heel.lua"]={["Path"]="scripts/actions/abilities/pets/back_heel.lua",["SHA256"]="906424c8c991058e747a1ff09207080406ea149cd468b82be69bc052ee6de850",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'back_heel_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/barracuda_dive.lua"]={["Path"]="scripts/actions/abilities/pets/barracuda_dive.lua",["SHA256"]="6a2944b42ee031641b08eb2ddf1d1bc13e5c54b19641a4a9f5f7bdb7a0c035b9",["Text"]="-----------------------------------\n-- Barracude Dive\n-- Family: Avatar (Leviathan)\n-- Description: Deals Physical damage to a single target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.0, 2.0, 2.0 }\n    params.fTPSubsequentHits = { 2.0, 2.0, 2.0 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    -- params.accuracyModifier   = { 0, 0, 0 } -- TODO: JP Wiki/Patch notes state this has an accuracy modifier.\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/beak_lunge.lua"]={["Path"]="scripts/actions/abilities/pets/beak_lunge.lua",["SHA256"]="a5a98a8d25f3ff12501eb788830b402766b20deb9a09806edc1dc2dbd94b9f58",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'beak_lunge_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/big_scissors.lua"]={["Path"]="scripts/actions/abilities/pets/big_scissors.lua",["SHA256"]="63c0ea6eabde31b580946362ba9afcf1ac8dce92b4c0cae74700fb5bc2c57971",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'big_scissors_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/blaster.lua"]={["Path"]="scripts/actions/abilities/pets/blaster.lua",["SHA256"]="24176cc18bb0a63978b5106f31142e46d309206e9fed442cddabe47d861f73c2",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'blaster_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/blindside.lua"]={["Path"]="scripts/actions/abilities/pets/blindside.lua",["SHA256"]="258a77c4d7badd0aade20ce273e933596e1e293cea2849a9bd2a4140219dfa37",["Text"]="-----------------------------------\n-- Blindside\n-- Family: Avatar (Diabolos)\n-- Description: Deals Physical damage to a single target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.0, 2.0, 2.0 } -- TODO: Capture fTPs\n    params.fTPSubsequentHits = { 2.0, 2.0, 2.0 }\n    -- params.str_wSC           = 0.20 -- TODO: Capture wSCs\n    -- params.mnd_wSC           = 0.20\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/blizzard_ii.lua"]={["Path"]="scripts/actions/abilities/pets/blizzard_ii.lua",["SHA256"]="093e1126f35985cd3236f7c558a47776115d542e4f69c2cd245b151b1b50895f",["Text"]="-----------------------------------\n-- Blizzard II\n-- Family: Shiva (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 1.500, 2.750, 3.125 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.ICE\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.ICE\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/blizzard_iv.lua"]={["Path"]="scripts/actions/abilities/pets/blizzard_iv.lua",["SHA256"]="c9dc27b3cf1995831fc61644ff00d9db62188706cd5921359e4488eb127ad6d0",["Text"]="-----------------------------------\n-- Blizzard IV\n-- Family: Shiva (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 3.6250, 5.3125, 6.1250 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.ICE\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.ICE\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/blockhead.lua"]={["Path"]="scripts/actions/abilities/pets/blockhead.lua",["SHA256"]="991c911e16d858a7dddb43cdf0ab770ade4cd93b705b627f0b6be18d32e3c971",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'blockhead_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/brain_crush.lua"]={["Path"]="scripts/actions/abilities/pets/brain_crush.lua",["SHA256"]="b3b0323f2edb4090863c9a43bdded37b310adf5c353aa0a8275100fc7d2dda6e",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'brain_crush_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/bubble_curtain.lua"]={["Path"]="scripts/actions/abilities/pets/bubble_curtain.lua",["SHA256"]="8037cefac8c701b5417a0ad134e3ad892e898074139438fe144db03c2c51bdea",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'bubble_curtain_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/bubble_shower.lua"]={["Path"]="scripts/actions/abilities/pets/bubble_shower.lua",["SHA256"]="0fdbb51ff3f124bfaaf9964f3b357dc1462d45d9c20461ce3fa1fcf0c273a004",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'bubble_shower_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/burning_strike.lua"]={["Path"]="scripts/actions/abilities/pets/burning_strike.lua",["SHA256"]="0164c12fb809a2b95931c4262fefd47d92f21d6da5a1a12ac2d08334a9fcf42e",["Text"]="-----------------------------------\n-- Burning Strike\n-- Family: Avatar (Ifrit)\n-- Description: Deals hybrid Physical/Magical(Fire) damage to a single target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage         = pet:getWeaponDmg()\n    params.numHits            = 1\n    params.fTP                = { 2.75, 2.75, 2.75 }\n    params.fTPSubsequentHits  = { 2.75, 2.75, 2.75 }\n    params.str_wSC            = 0.20\n    params.int_wSC            = 0.20\n    params.attackType         = xi.attackType.PHYSICAL\n    params.damageType         = xi.damageType.BLUNT\n    params.hybridSkill        = true\n    params.hybridSkillElement = xi.element.FIRE\n    params.hybridAttackType   = xi.attackType.MAGICAL\n    params.hybridDamageType   = xi.damageType.FIRE\n    params.shadowBehavior     = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    local totalDamage = 0\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        if info.damage > 0 then\n            target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n            totalDamage = totalDamage + info.damage\n        end\n\n        if info.hybridDamage > 0 and target:getHP() > 0 then\n            target:takeDamage(info.hybridDamage, pet, info.hybridAttackType, info.hybridDamageType)\n            totalDamage = totalDamage + info.hybridDamage\n        end\n    end\n\n    return totalDamage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/camisado.lua"]={["Path"]="scripts/actions/abilities/pets/camisado.lua",["SHA256"]="6e4b216640fcc0e8d684eab43b5acfa3d4eacd5cfaf11ec7235e8c72c809f761",["Text"]="-----------------------------------\n-- Camisado\n-- Family: Avatar (Diabolos)\n-- Description: Deals Physical damage to a target. Additional Effect: Knockback\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.0, 2.0, 2.0 }\n    params.fTPSubsequentHits = { 2.0, 2.0, 2.0 }\n    params.str_wSC           = 0.20\n    params.mnd_wSC           = 0.20\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    -- params.accuracyModifier    = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        -- TODO: Knockback may not yet be hooked up to abilities.\n        -- action:knockback(target:getID(), xi.action.knockback.LEVEL3)\n\n        -- TODO: Some equipment that reduces movement speed can reduce knockback distance. (Example: Plumb Boots)\n        -- https://discord.com/channels/392903136336936960/883227978002206751/1280243231635804262\n        -- https://discord.com/channels/443544205206355968/443893540922064896/1376405495845355661\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/chaotic_eye.lua"]={["Path"]="scripts/actions/abilities/pets/chaotic_eye.lua",["SHA256"]="67ffaba8c75573a1fc6165f76c338918e14b4029494bce5a8340523cd77b674b",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'chaotic_eye_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/chaotic_strike.lua"]={["Path"]="scripts/actions/abilities/pets/chaotic_strike.lua",["SHA256"]="3dbc02949d0f24f300f35b4c3a94a0cfabaa7f6a2d8a0a47b47a796bd2b4c1b5",["Text"]="-----------------------------------\n-- Chaotic Strike\n-- Family: Avatar (Ramuh)\n-- Description: Delivers a threefold attack that deals Physical damage to a target. Additional Effect: Stun\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 3\n    params.fTP               = { 10.00, 10.00, 10.00 }\n    params.fTPSubsequentHits = { 10.00, 10.00, 10.00 }\n    params.str_wSC           = 0.20\n    params.int_wSC           = 0.20\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_3\n    params.canCrit           = true\n    params.criticalChance    = { 0.10, 0.20, 0.25 } -- TODO: Capture crit rate\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.STUN, power = 1, duration = 12 },\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/charged_whisker.lua"]={["Path"]="scripts/actions/abilities/pets/charged_whisker.lua",["SHA256"]="375a6a791af0a68ff9d2293ee6b8487b76e6216858ff4c1048641bd7f1fbc5bd",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'charged_whisker_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/choke_breath.lua"]={["Path"]="scripts/actions/abilities/pets/choke_breath.lua",["SHA256"]="f7a918eb27aff9a3ab2df9480d4d8f56c99eb905065defcba8fbd26cbbd5b9f1",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'choke_breath_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/chomp_rush.lua"]={["Path"]="scripts/actions/abilities/pets/chomp_rush.lua",["SHA256"]="34c7af119b95898d17645fdb148af22eebeb14c68ed46997429344e7d1dcc92a",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'chomp_rush_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/chronoshift.lua"]={["Path"]="scripts/actions/abilities/pets/chronoshift.lua",["SHA256"]="7978d34982aa14e78a57990169a69a0e7af23040b3f05bd5bc04e10f949e6df3",["Text"]="-----------------------------------\n-- Chronoshift\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    local effectCount = 0\n    local effectID    = pet:getLocalVar('aEffectID') or 0    -- Retrive the absorbed effect's ID\n    local effect      = pet:getStatusEffect(effectID) or nil -- Find that effect on Atomos\n\n    if effect then\n        -- Delete old effect if on target already\n        target:delStatusEffectSilent(effectID)\n        -- Add the stolen effect to the party\n        target:copyStatusEffect(effect)\n        petskill:setMsg(xi.msg.basic.RECEIVE_MAGICAL_EFFECT)\n        effectCount = 1\n    else\n        petskill:setMsg(xi.msg.basic.NO_EFFECT)\n    end\n\n    pet:timer(5000, function()\n        if summoner then\n            summoner:despawnPet()\n        end\n    end)\n\n    return effectCount\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/clarsach_call.lua"]={["Path"]="scripts/actions/abilities/pets/clarsach_call.lua",["SHA256"]="6095effb1ae74ce481a1fe2afb8466d2b2dfb7be3b3f1b7d914b927ad8d2eeb3",["Text"]="-----------------------------------\n-- Clarsach Call\n-- Family: Siren (Player Pet)\n-- Note: Siren's Astral Flow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\n-- https://www.bg-wiki.com/ffxi/Clarsach_Call\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 9, 9, 9 } -- TODO: Need data on fTPs, using standard astral flow ftps for now.\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WIND\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WIND\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.WIPE_SHADOWS -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    summoner:setMP(0)\n\n    pet:addStatusEffect(xi.effect.ATTACK_BOOST, { power = 25, duration = 180, origin = pet })\n    pet:addStatusEffect(xi.effect.DEFENSE_BOOST, { power = 25, duration = 180, origin = pet })\n    pet:addStatusEffect(xi.effect.MAGIC_ATK_BOOST, { power = 25, duration = 180, origin = pet })\n    pet:addStatusEffect(xi.effect.MAGIC_DEF_BOOST, { power = 25, duration = 180, origin = pet })\n    pet:addStatusEffect(xi.effect.EVASION_BOOST, { power = 50, duration = 180, origin = pet })\n    pet:addStatusEffect(xi.effect.MAGIC_EVASION_BOOST, { power = 50, duration = 180, origin = pet })\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/claw.lua"]={["Path"]="scripts/actions/abilities/pets/claw.lua",["SHA256"]="1997887c78b4ade28903a5e877b96c69737e4eb69ba2ad431d0c29e54dc0c770",["Text"]="-----------------------------------\n-- Claw\n-- Family: Avatar (Garuda)\n-- Description: Deals Physical damage to a single target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.0, 2.0, 2.0 }\n    params.fTPSubsequentHits = { 2.0, 2.0, 2.0 }\n    params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.PIERCING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.canCrit           = true\n    params.criticalChance    = { 0.10, 0.20, 0.25 } -- TODO: Capture crit rate\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/claw_cyclone.lua"]={["Path"]="scripts/actions/abilities/pets/claw_cyclone.lua",["SHA256"]="6cbc69ac00317d3c5370b7ed0b8cad56ef759377a67e87d5a5a779bfe0537edb",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'claw_cyclone_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/concentric_pulse.lua"]={["Path"]="scripts/actions/abilities/pets/concentric_pulse.lua",["SHA256"]="d5f88856db06e2e2f69da4a13e31f8fd1acfae7c327956425c8ca9de3dcbb282",["Text"]="-----------------------------------\n-- Concentric Pulse\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.geomancer.geoOnConcentricPulseAbilityCheck(player, target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, master, action)\n    local masterEquippedHead = xi.equipment.getUsableEquipID(master, xi.slot.HEAD)\n    local dmgBoost           = master:getJobPointLevel(xi.jp.CONCENTRIC_PULSE_EFFECT)\n    local dmg                = pet:getHP()\n\n    if\n        masterEquippedHead == xi.item.BAGUA_GALERO_P2 or\n        masterEquippedHead == xi.item.BAGUA_GALERO_P3\n    then\n        dmg = pet:getMaxHP()\n    end\n\n    if dmgBoost > 0 then\n        dmg = dmg + math.floor(dmg * dmgBoost / 100)\n    end\n\n    -- TODO: Affected by Phalanx, MDT, Magic Damage % modifiers, OneForAll?\n    dmg = utils.handleStoneskin(target, dmg, xi.attackType.MAGICAL)\n\n    target:takeDamage(dmg, pet, xi.attackType.MAGICAL, xi.damageType.NONE)\n\n    pet:timer(200, function(mobArg)\n        mobArg:setHP(0)\n    end)\n\n    return dmg\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/corrosive_ooze.lua"]={["Path"]="scripts/actions/abilities/pets/corrosive_ooze.lua",["SHA256"]="bd021b23cc06544c4f783b0ab67b58bc9a8ec552ebf60b7d2e59d48415f4aae4",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'corrosive_ooze_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/crescent_fang.lua"]={["Path"]="scripts/actions/abilities/pets/crescent_fang.lua",["SHA256"]="2cd4af27bea85e830b5329d74b718afc093498b8949707941f0f10d717776216",["Text"]="-----------------------------------\n-- Crescent Fang M=6\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 1.50, 3.75, 6.00 } -- TODO: Capture 2000 fTP. Using 3.75 for now (Linear scaling).\n    params.fTPSubsequentHits = { 1.50, 3.75, 6.00 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.PIERCING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.PARALYSIS, power = 22, duration = 60 }, -- TODO: Capture power\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/crimson_howl.lua"]={["Path"]="scripts/actions/abilities/pets/crimson_howl.lua",["SHA256"]="3e164c5152aa81abe4e3e200102ba81df0f295a16ce38ba3da4509c5dc14b599",["Text"]="-----------------------------------\n-- Crimson Howl\n-- Family: Avatar (Ifrit)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local baseDuration = 60\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n    local power        = (math.floor((pet:getMainLvl() / 4) + 4.75) / 256) * 100\n\n    if target:addStatusEffect(xi.effect.WARCRY, { power = power, duration = duration, origin = pet }) then\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return\n    end\n\n    return xi.effect.WARCRY\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/crossthrash.lua"]={["Path"]="scripts/actions/abilities/pets/crossthrash.lua",["SHA256"]="9bcc41e978d802cf4319da731e65f831d2eef94ab9f43ef5aab774bdfbe7ca21",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nlocal skillName = 'crossthrash_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/cursed_sphere.lua"]={["Path"]="scripts/actions/abilities/pets/cursed_sphere.lua",["SHA256"]="b722c4340946d49dd2612e35a7f6a29d5befeb6ba28e09a8259bb939e609f344",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'cursed_sphere_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"}};
